    function parseResponse(response) {
		var answer = response.responseXML.documentElement.getAttribute('answer');
        if ("" != answer) {
        var dateRanges = JSON.parse(answer);
		console.log(dateRanges);

        // 显示返回的日期范围
        //g_form.addInfoMessage('Begin Today: ' + dateRanges.beginningOfToday);
        //g_form.addInfoMessage('End Today: ' + dateRanges.endOfToday);
		g_form.setValue('start_date',dateRanges.endOfToday);
		g_form.setValue('end_date',dateRanges.beginningOfToday);

       /* g_form.addInfoMessage('Begin Tomorrow: ' + dateRanges.beginTomorrow);
